UPDATE T_AGENT_STATUS
   SET JNL_MODE = #{jnlMode,jdbcType=CHAR},
       UPD_DT   = CURRENT_TIMESTAMP
 WHERE TERM_GROUP_ID = #{termGroupId,jdbcType=CHAR}
   AND TERM_ID       = #{termId,jdbcType=VARCHAR}

UPDATE T_AGENT_STATUS
   SET LAST_JNL_DATE = SUBSTR(#{jnlDate,jdbcType=CHAR}, 1, 8),
       LAST_JNL_TIME = SUBSTR(#{jnlTime,jdbcType=CHAR}, 1, 6),
       UPD_DT        = CURRENT_TIMESTAMP
 WHERE TERM_GROUP_ID = #{termGroupId,jdbcType=CHAR}
   AND TERM_ID       = #{termId,jdbcType=VARCHAR}
